<?php
require_once '../config/database.php'; require_once '../includes/auth.php'; require_role('teacher'); $page_title='Журнал оценок';
$q=$pdo->prepare('SELECT id FROM teachers WHERE user_id=?');$q->execute([$_SESSION['user']['id']]);$tid=(int)$q->fetchColumn();
$groupsStmt=$pdo->prepare('SELECT DISTINCT g.id,g.name FROM lessons l JOIN groups g ON g.id=l.group_id WHERE l.teacher_id=? ORDER BY g.name');$groupsStmt->execute([$tid]);$groups=$groupsStmt->fetchAll();
$subjectsStmt=$pdo->prepare('SELECT DISTINCT s.id,s.name FROM lessons l JOIN subjects s ON s.id=l.subject_id WHERE l.teacher_id=? ORDER BY s.name');$subjectsStmt->execute([$tid]);$subjects=$subjectsStmt->fetchAll();
$groupId=(int)($_GET['group_id']??$_POST['group_id']??($groups[0]['id']??0));$subjectId=(int)($_GET['subject_id']??$_POST['subject_id']??($subjects[0]['id']??0));
$canGrade=false;if($groupId&&$subjectId){$checkPair=$pdo->prepare('SELECT COUNT(*) FROM lessons WHERE teacher_id=? AND group_id=? AND subject_id=?');$checkPair->execute([$tid,$groupId,$subjectId]);$canGrade=(bool)$checkPair->fetchColumn();}
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$pdo->prepare('DELETE FROM grades WHERE id=? AND teacher_id=?')->execute([$id,$tid]);$_SESSION['flash_success']='Оценка удалена.';header('Location: grades.php?group_id='.$groupId.'&subject_id='.$subjectId);exit;}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['save_grades'])){
    if(!$canGrade){$_SESSION['flash_error']='Выбранная группа и предмет не закреплены за вами в расписании.';header('Location: grades.php');exit;}
    $date=$_POST['grade_date']??date('Y-m-d');$saved=0;
    foreach(($_POST['grade']??[]) as $studentId=>$grade){
        if($grade==='')continue;$grade=(int)$grade;$studentId=(int)$studentId;if($grade<2||$grade>5)continue;
        $check=$pdo->prepare('SELECT COUNT(*) FROM students WHERE id=? AND group_id=?');$check->execute([$studentId,$groupId]);if(!$check->fetchColumn())continue;
        $comment=trim($_POST['comment'][$studentId]??'');
        $pdo->prepare('INSERT INTO grades(student_id,subject_id,teacher_id,grade,grade_date,comment) VALUES(?,?,?,?,?,?)')->execute([$studentId,$subjectId,$tid,$grade,$date,$comment]);$saved++;
    }
    $_SESSION['flash_success']=$saved?'Сохранено оценок: '.$saved.'.':'Новые оценки не выбраны.';header('Location: grades.php?group_id='.$groupId.'&subject_id='.$subjectId);exit;
}
$students=[];if($groupId){$q=$pdo->prepare('SELECT id,surname,name,patronymic FROM students WHERE group_id=? AND status="active" ORDER BY surname,name');$q->execute([$groupId]);$students=$q->fetchAll();}
$history=[];if($groupId&&$subjectId){$q=$pdo->prepare("SELECT gr.*,CONCAT(st.surname,' ',st.name) student_name FROM grades gr JOIN students st ON st.id=gr.student_id WHERE st.group_id=? AND gr.subject_id=? AND gr.teacher_id=? ORDER BY gr.grade_date DESC,gr.id DESC LIMIT 80");$q->execute([$groupId,$subjectId,$tid]);$history=$q->fetchAll();}
include '../includes/header.php';?>
<div class="panel"><div class="section-head"><h2>Выберите группу и предмет</h2></div><form method="get" class="filters"><select name="group_id" onchange="this.form.submit()"> <?php foreach($groups as $g):?><option value="<?=$g['id']?>" <?=$groupId==$g['id']?'selected':''?>><?=htmlspecialchars($g['name'])?></option><?php endforeach;?></select><select name="subject_id" onchange="this.form.submit()"> <?php foreach($subjects as $s):?><option value="<?=$s['id']?>" <?=$subjectId==$s['id']?'selected':''?>><?=htmlspecialchars($s['name'])?></option><?php endforeach;?></select></form></div>
<?php if($students&&$subjectId&&$canGrade):?><div class="panel" style="margin-top:20px"><h2>Поставить оценки</h2><form method="post"><input type="hidden" name="group_id" value="<?=$groupId?>"><input type="hidden" name="subject_id" value="<?=$subjectId?>"><input type="hidden" name="save_grades" value="1"><div class="filter-row"><label>Дата <input type="date" name="grade_date" value="<?=date('Y-m-d')?>"></label></div><div class="table-wrap"><table><tr><th>Студент</th><th>Оценка</th><th>Комментарий</th></tr><?php foreach($students as $st):?><tr><td><b><?=htmlspecialchars(trim("$st[surname] $st[name] $st[patronymic]"))?></b></td><td><select name="grade[<?=$st['id']?>]"><option value="">—</option><option>5</option><option>4</option><option>3</option><option>2</option></select></td><td><input name="comment[<?=$st['id']?>]" placeholder="Контрольная, ответ у доски..."></td></tr><?php endforeach;?></table></div><br><button class="btn success">⭐ Сохранить оценки</button></form></div><?php else:?><div class="panel" style="margin-top:20px"><div class="empty-state"><div class="emoji">⭐</div>Нет доступных студентов или занятий для выбранных параметров.</div></div><?php endif;?>
<div class="panel" style="margin-top:20px"><h2>Последние оценки</h2><div class="table-wrap"><table><tr><th>Дата</th><th>Студент</th><th>Оценка</th><th>Комментарий</th><th></th></tr><?php foreach($history as $r):?><tr><td><?=date('d.m.Y',strtotime($r['grade_date']))?></td><td><?=htmlspecialchars($r['student_name'])?></td><td><span class="grade grade-<?=$r['grade']?>"><?=$r['grade']?></span></td><td><?=htmlspecialchars($r['comment'])?></td><td><a class="btn danger" href="?group_id=<?=$groupId?>&subject_id=<?=$subjectId?>&delete=<?=$r['id']?>" onclick="return confirm('Удалить эту оценку?')">Удалить</a></td></tr><?php endforeach;?></table></div></div>
<?php include '../includes/footer.php';?>
